  (item) => !item.key.startsWith('FOOTBALL_'),
);

// Preserve today's default cards; organizers add singles and flexible formats explicitly.
export const DEFAULT_VISIBLE_RACKET_FORMAT_OPTIONS = DEFAULT_RACKET_FORMAT_OPTIONS.filter(
  (item) =>
    !item.key.endsWith('SINGLES') &&
    item.key !== 'OPEN_DOUBLES',
);

export const DEFAULT_FOOTBALL_FORMAT_OPTIONS = QUICK_FORMAT_OPTIONS.filter(
  (item) => item.key.startsWith('FOOTBALL_'),
);

export const DEFAULT_RACKET_FORMATS: string[] = DEFAULT_RACKET_FORMAT_OPTIONS.map(
  (item) => item.key,
);
export const DEFAULT_FOOTBALL_FORMATS: string[] = DEFAULT_FOOTBALL_FORMAT_OPTIONS.map(
  (item) => item.key,
);

const genderRestrictionByFormat: Record<string, GenderRestriction | undefined> = {
  MALE_SINGLES: GenderRestriction.MALE,
  FEMALE_SINGLES: GenderRestriction.FEMALE,
  MALE_DOUBLES: GenderRestriction.MALE,
  FEMALE_DOUBLES: GenderRestriction.FEMALE,
  MIXED_DOUBLES: GenderRestriction.MIXED,
  FOOTBALL_MALE: GenderRestriction.MALE,
  FOOTBALL_FEMALE: GenderRestriction.FEMALE,
};

export const toDivisionInput = (
  formatKey: string,
  divisionName: string,
  bracketType: 'single_elimination' | 'double_elimination' | 'round_robin' | 'group_stage_knockout',
  maxParticipants: number,
  startDate?: string,
  registrationEndDate?: string,
): CreateDivisionInput => {
  const genderRestriction = genderRestrictionByFormat[formatKey];
  return {
    name: divisionName,
    matchType: formatKey.includes('SINGLES')
      ? MatchTypeDB.SINGLES
      : formatKey.includes('MIXED_DOUBLES')
        ? MatchTypeDB.MIXED_DOUBLES
        : MatchTypeDB.DOUBLES,
    ...(genderRestriction ? { genderRestriction } : {}),
    maxParticipants,
    entryFee: 0,
    bracketType: bracketType.toUpperCase() as CreateDivisionInput['bracketType'],
    startDate: startDate ?? null,
    registrationEndDate: registrationEndDate ?? null,
  };
};

