  const onSubmit = async (values: QuickValues) => {
    try {
…
      const createPayload: Parameters<typeof tournamentsApi.createLiteTournament>[0] = {
…
        entryFee: communityId || !feeConfig?.allowEntryFees ? 0 : values.entryFee,
        registrationStartDate: toApiIsoDateTime(effectiveRegistrationStart) ?? undefined,
        registrationEndDate: toApiIsoDateTime(effectiveRegistrationEnd) ?? undefined,
        startDate: toApiIsoDateTime(values.startDate) ?? undefined,
        endDate: toApiIsoDateTime(values.endDate) ?? undefined,
        durationMinutes: values.startDate && values.endDate
          ? Math.min(14400, Math.max(15, Math.round((new Date(values.endDate).getTime() - new Date(values.startDate).getTime()) / 60000)))
          : undefined,
        durationHours: values.startDate && values.endDate
          ? Number((Math.min(14400, Math.max(15, Math.round((new Date(values.endDate).getTime() - new Date(values.startDate).getTime()) / 60000))) / 60).toFixed(1))
          : undefined,
        venueName: values.venueName ? values.venueName.trim() : undefined,
        locationAddress: values.locationAddress ? values.locationAddress.trim() : undefined,
        province: provinceName || undefined,
        provinceCode: values.province || undefined,
        ward: wardName || undefined,
        wardCode: values.ward || undefined,
        galleryImages: values.galleryImages.length > 0 ? values.galleryImages : undefined,
        logoUrl: values.logoUrl || undefined,
        bannerUrl: values.bannerUrl || undefined,
        contactInfo: {
          phone: user?.phoneNumber || undefined,
          email: user?.email || undefined,
        },
        teamSize: values.sport === 'football' ? (Number(values.teamSize) as 5 | 7 | 11) : undefined,
        teamSizeOptions: values.sport === 'football' && values.teamSizeOptions.length > 0 ? values.teamSizeOptions : undefined,
        minTeamSize: values.sport === 'football' ? values.minTeamSize : undefined,
        maxTeamSize: values.sport === 'football' ? values.maxTeamSize : undefined,
        maxReserve: values.sport === 'football' ? values.maxReserve : undefined,
        footballHalvesCount: values.sport === 'football' ? values.footballHalvesCount : undefined,
        footballHalfDuration: values.sport === 'football' ? values.footballHalfDuration : undefined,
        footballAllowDraw: values.sport === 'football' ? values.footballAllowDraw : undefined,
        twoLegged: values.sport === 'football' ? values.twoLegged : undefined,
        awayGoalsRule: values.sport === 'football' ? values.awayGoalsRule : undefined,
        penaltyShootout: values.sport === 'football' ? values.penaltyShootout : undefined,
      };

      const response = await tournamentsApi.createLiteTournament(createPayload);

      router.push(
        communityId
          ? `/lite/tournaments/${response.id}/manage`
          : `/organizer/tournaments/${response.id}/manage`,
      );
    } catch (error: unknown) {
      toast.error(getErrorMessage(error, translate('createFailed')));
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <main className="min-h-screen bg-slate-50/70 px-3 py-3 sm:px-6 sm:py-4">
      <div className="mx-auto max-w-7xl">
        {/* Header Bar: Tinh gọn 1 hàng */}
