import { ApiProperty, ApiPropertyOptional } from '@nestjs/swagger';
import {
  IsString,
  IsNotEmpty,
  IsOptional,
  IsNumber,
  IsBoolean,
  IsUUID,
  IsDateString,
  IsArray,
  Min,
  Max,
  IsIn,
  ValidateNested,
  IsInt,
  IsObject,
} from 'class-validator';
import { Type } from 'class-transformer';

class CreateLiteDivisionConfigDto {
  @ApiProperty({ example: 'Đôi Nam' })
  @IsString()
  @IsNotEmpty()
  name: string;

  @ApiProperty({ enum: ['SINGLES', 'DOUBLES', 'MIXED_DOUBLES'] })
  @IsString()
  @IsIn(['SINGLES', 'DOUBLES', 'MIXED_DOUBLES'])
  matchType: 'SINGLES' | 'DOUBLES' | 'MIXED_DOUBLES';

  @ApiPropertyOptional({ enum: ['MALE', 'FEMALE', 'MIXED'] })
  @IsString()
  @IsOptional()
  @IsIn(['MALE', 'FEMALE', 'MIXED'])
  genderRestriction?: 'MALE' | 'FEMALE' | 'MIXED';

  @ApiPropertyOptional({ example: 64, description: 'Số người/đội tối đa cho nội dung' })
  @IsNumber()
  @IsOptional()
  @Min(2)
  @Max(128)
  maxParticipants?: number;

  @ApiPropertyOptional({ enum: ['SINGLE_ELIMINATION', 'DOUBLE_ELIMINATION', 'ROUND_ROBIN', 'GROUP_STAGE_KNOCKOUT'] })
  @IsString()
  @IsOptional()
  @IsIn(['SINGLE_ELIMINATION', 'DOUBLE_ELIMINATION', 'ROUND_ROBIN', 'GROUP_STAGE_KNOCKOUT'])
  bracketType?: 'SINGLE_ELIMINATION' | 'DOUBLE_ELIMINATION' | 'ROUND_ROBIN' | 'GROUP_STAGE_KNOCKOUT';

  @ApiPropertyOptional({ example: 1000 })
  @IsNumber()
  @IsOptional()
  @Min(0)
  minElo?: number | null;

  @ApiPropertyOptional({ example: 1600 })
  @IsNumber()
  @IsOptional()
  @Min(0)
  maxElo?: number | null;

  @ApiPropertyOptional({ example: '2026-10-15T00:00:00.000Z' })
  @IsDateString()
  @IsOptional()
  startDate?: string | null;

  @ApiPropertyOptional({ example: '2026-10-14T23:59:00.000Z' })
  @IsDateString()
  @IsOptional()
  registrationEndDate?: string | null;

  @ApiPropertyOptional({ example: 'Giải nhất 3.000.000đ' })
  @IsString()
  @IsOptional()
  prizeDescription?: string | null;
}

export class CreateLiteTournamentDto {
  @ApiProperty({
    example: 'Giải Cầu lông Cuối Tuần',
    description: 'Tên giải đấu',
  })
  @IsString()
  @IsNotEmpty()
  name: string;

  @ApiPropertyOptional({ example: 'uuid-community', description: 'ID câu lạc bộ; bỏ trống để tạo giải nhanh riêng bằng quyền Organizer' })
  @IsUUID()
  @IsOptional()
  communityId?: string;

  @ApiPropertyOptional({ description: 'Địa điểm đã tồn tại; dùng chung với buổi giao lưu CLB nếu có' })
  @IsUUID()
  @IsOptional()
  venueId?: string;

  @ApiPropertyOptional({
    example: 'PUBLIC',
    description: 'Phạm vi giải: PUBLIC là giải mở rộng, CLUB là giải nội bộ câu lạc bộ',
    enum: ['CLUB', 'PUBLIC'],
  })
  @IsString()
  @IsOptional()
  @IsIn(['CLUB', 'PUBLIC'])
  tournamentType?: 'CLUB' | 'PUBLIC';

  @ApiPropertyOptional({ example: 'https://cdn.../banner.jpg', description: 'Ảnh bìa tùy chọn' })
  @IsString()
  @IsOptional()
  bannerUrl?: string;

  @ApiPropertyOptional({ example: 'https://cdn.../logo.jpg', description: 'Logo tùy chọn' })
  @IsString()
  @IsOptional()
  logoUrl?: string;

  @ApiPropertyOptional({ example: 'Giải thưởng giao lưu', description: 'Mô tả giải thưởng tùy chọn' })
  @IsString()
  @IsOptional()
  prizeDescription?: string;

  @ApiPropertyOptional({ example: { phone: '0900000000', email: 'btc@example.com' }, description: 'Liên hệ BTC tùy chọn' })
  @IsOptional()
  contactInfo?: Record<string, string>;

  @ApiProperty({
    example: 'badminton',
    description: 'Môn thi đấu (slug)',
    enum: ['badminton', 'tennis', 'pickleball', 'table_tennis', 'football'],
  })
  @IsString()
  @IsIn(['badminton', 'tennis', 'pickleball', 'table_tennis', 'football'])
  sport: string;

  @ApiPropertyOptional({
    example: 'singles',
    description: 'Hình thức: đánh đơn, đôi hoặc đôi nam nữ',
    enum: ['singles', 'doubles', 'mixed_doubles'],
  })
  @IsString()
  @IsOptional()
  @IsIn(['singles', 'doubles', 'mixed_doubles'])
  format?: string;

  @ApiPropertyOptional({
    example: 'ORGANIZER',
    description:
      'Cách ghép đôi cho nội dung đôi. ORGANIZER bật BTC ghép đôi (mặc định); SELF chỉ cho người chơi mời đồng đội trực tiếp/QR.',
    enum: ['ORGANIZER', 'SELF'],
  })
  @IsString()
  @IsOptional()
  @IsIn(['ORGANIZER', 'SELF'])
  doublesPairingMode?: 'ORGANIZER' | 'SELF';

  @ApiPropertyOptional({
    example: 'MALE',
    description:
      'Giới hạn giới tính cho hình thức đơn/đôi; bỏ trống là không ràng buộc',
    enum: ['MALE', 'FEMALE', 'MIXED'],
  })
  @IsString()
  @IsOptional()
  @IsIn(['MALE', 'FEMALE', 'MIXED'])
  genderRestriction?: 'MALE' | 'FEMALE' | 'MIXED';

  @ApiPropertyOptional({
    example: 'single_elimination',
    description:
      'Thể thức thi đấu. Chỉ hỗ trợ: single_elimination, double_elimination, round_robin, group_stage_knockout.',
    enum: [
      'single_elimination',
      'double_elimination',
      'round_robin',
      'group_stage_knockout',
    ],
  })
  @IsString()
  @IsOptional()
  @IsIn([
    'single_elimination',
    'double_elimination',
    'round_robin',
    'group_stage_knockout',
  ])
  bracketType?: string;

  @ApiPropertyOptional({ example: 16, description: 'Số đội tối đa (2-128)' })
  @IsNumber()
  @IsOptional()
  @Min(2)
  @Max(128)
  maxTeams?: number;

  @ApiPropertyOptional({
    type: [CreateLiteDivisionConfigDto],
    description: 'Các nội dung đã cấu hình trong tạo nhanh. Đây là DTO nghiệp vụ, không nhận state UI như selectedFormats.',
  })
  @IsArray()
  @IsOptional()
  @ValidateNested({ each: true })
  @Type(() => CreateLiteDivisionConfigDto)
  divisions?: CreateLiteDivisionConfigDto[];

  @ApiPropertyOptional({ example: 20000, description: 'Phí tham gia PUBLIC bằng VND; giải CLUB luôn miễn phí' })
  @IsNumber()
  @IsInt()
  @IsOptional()
  @Min(0)
  entryFee?: number;

  @ApiPropertyOptional({ example: 'uuid-parent-tournament', description: 'Giải đấu cha (series)' })
  @IsUUID()
  @IsOptional()
  parentId?: string;

  @ApiPropertyOptional({ example: 3000, description: 'Tổng ELO tối đa của một đội' })
  @IsNumber()
  @IsOptional()
  @Min(0)
  maxCombinedElo?: number;

  @ApiPropertyOptional({ example: 500, description: 'Chênh lệch ELO tối đa giữa đồng đội' })
  @IsNumber()
  @IsOptional()
  @Min(0)
  maxTeammateGap?: number;

  @ApiPropertyOptional({ example: [5, 7, 11], enum: [5, 7, 11], isArray: true })
  @IsArray()
  @IsOptional()
  @IsNumber({}, { each: true })
  @IsIn([5, 7, 11], { each: true })
  teamSizeOptions?: Array<5 | 7 | 11>;

  @ApiPropertyOptional({ example: 7, enum: [5, 7, 11] })
  @IsNumber()
  @IsOptional()
  @IsIn([5, 7, 11])
  minTeamSize?: 5 | 7 | 11;

