  );
}

export function getInitialRegistrationDivisionId<T extends RegistrationDivision>(
  divisions: readonly T[],
  preferredDivisionId?: string | null,
): string {
  const activeDivisions = getActiveRegistrationDivisions(divisions);
  if (
    preferredDivisionId &&
    activeDivisions.some((division) => division.id === preferredDivisionId)
  ) {
    return preferredDivisionId;
  }

  return activeDivisions.length === 1 ? activeDivisions[0].id : '';
}

