  const handleAddReferee = async (e: React.FormEvent) => {
    e.preventDefault(); if (!refereeEmail.trim()) return;
    setIsAddingReferee(true);
    try { await tournamentsApi.addTournamentReferee(id, refereeEmail.trim()); toast.success('Đã gửi lời mời trọng tài!'); setRefereeEmail(''); await fetchReferees(); }
    catch (err) { toast.error(getErrorMessage(err)); }
    finally { setIsAddingReferee(false); }
  };

  const openDivisionEditor = (division: Division) => {
    setSelectedDivisionId(division.id);
    const divisionFormatKey: MatchFormatOptionValue = division.matchType === MatchTypeDB.MIXED_DOUBLES || division.genderRestriction === GenderRestriction.MIXED
      ? 'MIXED_DOUBLES'
      : division.matchType === MatchTypeDB.SINGLES
        ? division.genderRestriction === GenderRestriction.FEMALE ? 'FEMALE_SINGLES' : 'MALE_SINGLES'
        : division.genderRestriction === GenderRestriction.FEMALE ? 'FEMALE_DOUBLES' : 'MALE_DOUBLES';
    setEditingDivision(division);
    setNewDivisionMatchType(normalizeMatchFormatForCategory(
      divisionFormatKey,
      selectedCategory,
    ));
    setNewDivisionName(division.name);
    setNewDivisionBracketType(division.bracketType ?? 'SINGLE_ELIMINATION');
    setNewDivisionEloEnabled(division.minElo != null || division.maxElo != null);
    setNewDivisionMinElo(division.minElo ?? null);
    setNewDivisionMaxElo(division.maxElo ?? null);
    setNewDivisionMaxParticipants(String(division.maxParticipants ?? 16));
    setNewDivisionLimitEnabled(division.maxParticipants != null);
    const hasEntryFeeOverride = division.entryFeeOverrideEnabled === true;
    setNewDivisionEntryFeeOverrideEnabled(hasEntryFeeOverride);
    setNewDivisionEntryFee(
      hasEntryFeeOverride
        ? String(division.entryFeeOverride ?? division.entryFee ?? '')
        : '',
    );
    const divisionRoundConfig = division.roundConfig as Record<string, unknown> | null | undefined;
    const divisionGroupsConfig = divisionRoundConfig?.groupsConfig as Record<string, unknown> | undefined;
    const divisionAdvancementConfig = divisionRoundConfig?.advancementConfig as Record<string, unknown> | undefined;
    const divisionPlayoffConfig = divisionRoundConfig?.playoffConfig as Record<string, unknown> | undefined;
    const fallbackKind = normalizeSportRuleKindForCategory(
      inferSportRuleKindFromCategory(selectedCategory),
      selectedCategory,
    );
    setNewDivisionIsLiteMode(readExplicitScoringMode(division.roundConfig) !== 'STRICT');
    applyNewDivisionScoringDraft(division.roundConfig, fallbackKind);
    setNewDivisionNumGroups(typeof divisionGroupsConfig?.numGroups === 'number'
      ? divisionGroupsConfig.numGroups
      : division.maxParticipants != null && division.maxParticipants >= 16 ? 4 : 2);
    setNewDivisionTeamsPerGroup(typeof divisionGroupsConfig?.teamsPerGroup === 'number' ? divisionGroupsConfig.teamsPerGroup : 4);
    setNewDivisionTeamsAdvancing(typeof divisionAdvancementConfig?.teamsAdvancing === 'number' ? divisionAdvancementConfig.teamsAdvancing : 2);
    setNewDivisionPlayoffType(divisionPlayoffConfig?.type === 'DOUBLE_ELIMINATION' ? 'DOUBLE_ELIMINATION' : 'SINGLE_ELIMINATION');
    setNewDivisionSeedingType(divisionPlayoffConfig?.seedingType === 'RANDOM' ? 'RANDOM' : 'SEEDED');
    applyDivisionFormValues(division);
    setIsCreateDivisionModalOpen(true);
  };

  const handleAttachExistingTournamentVenue = async (targetVenueId: string) => {
    if (!id) return;
    const existingVenue = venues.find((venue) => venue.id === targetVenueId);
